('3cb43038-4fb9-4ac9-850f-d317bcde43e4'::uuid, '066d5a99-4c5b-48c1-bf39-b37c78128228'::uuid, 1, $u$دل شکستہ ضرور ہے مگر ہارا نہیں ہے$u$, $u$منزل رائیگاں سہی سفر ناکارہ نہیں ہے$u$),
('25c90738-9d0f-4469-ae0f-5c1adb839e50'::uuid, '066d5a99-4c5b-48c1-bf39-b37c78128228'::uuid, 2, $u$کیا دوست، کیا محبت، کیا ہی منزل اوریہ نیا شہر$u$, $u$احمد ؔ  ہم یہاں سبھی کے ہیں پر کوئی ہمارا نہیں ہے$u$),
('a5cd9739-4eaa-466e-9150-c682ba846168'::uuid, 'b0f6419b-0ace-42f6-a28e-a494df6095a8'::uuid, 1, $u$اب کہ تنہا ہے دل اور سہارا کوئی نہیں$u$, $u$ڈوب چلے ہیں ساگر میں اور کنارہ کوئی نہیں$u$),
('f78d28a1-930e-42a2-bcc4-523b98116b0f'::uuid, 'b0f6419b-0ace-42f6-a28e-a494df6095a8'::uuid, 2, $u$شب ہجر کئی یادوں کے گھنیرے جنگل میں$u$, $u$لب بام تنہا بیٹھے ہیں اور چاند ستارہ کوئی نہیں$u$),
('9ec89eae-e58a-4db3-b465-60f54bd48ff3'::uuid, 'b0f6419b-0ace-42f6-a28e-a494df6095a8'::uuid, 3, $u$یوں تو گزر ہوا ہوگا کئی حسیں راہگزاروں سے$u$, $u$ہر پل سفر کو چلتے ہیں اور یاد نظارہ کوئی نہیں$u$),
('4bf3a9e0-e907-4ae3-ac26-3e8e251db1c8'::uuid, 'b0f6419b-0ace-42f6-a28e-a494df6095a8'::uuid, 4, $u$کیا دوست، کیا محبت، کیا ہی منزل اوریہ نیا شہر$u$, $u$احمد ہم یہاں سبھی کے ہیں اور بس ہمارا کوئی نہیں$u$),
